#!/usr/bin/env node

import { rmSync } from 'node:fs';
import { resolve } from 'node:path';

// `out` is entirely generated by electron-vite. Removing it before every
// production build prevents stale content-hashed chunks and source maps from
// surviving across builds and invalidating the packaged revision digest.
const outputDir = resolve(import.meta.dirname, '..', 'out');
rmSync(outputDir, { recursive: true, force: true });
console.log(`[desktop build] cleaned generated output: ${outputDir}`);
